const assert=require('node:assert/strict'),util=require('node:util'),native=require('node:crypto');
const subject=process.argv[2],api=subject==='native'?native:require('./platform.cjs');
const {createHook,AsyncLocalStorage,executionAsyncId}=require('node:async_hooks');
const results=[];
function error(fn){try{fn();return null;}catch(e){return {name:e.name,code:e.code,message:e.message};}}
async function group(name,fn){try{const value=await fn();results.push({name,status:'pass',value});}catch(e){results.push({name,status:'fail',error:{name:e.name,code:e.code,message:e.message,stack:e.stack}});}}
function checkPair(pair,type){assert.equal(pair.publicKey.type,'public');assert.equal(pair.privateKey.type,'private');assert.equal(pair.publicKey.asymmetricKeyType,type);assert.equal(pair.privateKey.asymmetricKeyType,type);const a=pair.publicKey.export({type:'spki',format:'der'}),b=api.createPublicKey(pair.privateKey).export({type:'spki',format:'der'});assert.equal(Buffer.compare(a,b),0);if(type==='dsa')assert.throws(()=>pair.publicKey.export({format:'jwk'}),{code:'ERR_CRYPTO_JWK_UNSUPPORTED_KEY_TYPE'});else {const pub=pair.publicKey.export({format:'jwk'});assert.equal('d' in pub,false);}return {type,private:pair.privateKey.type};}
function asyncPair(type,options){return new Promise((resolve,reject)=>api.generateKeyPair(type,options,function(error,publicKey,privateKey){if(error)return reject(error);resolve({publicKey,privateKey,job:this});}));}
(async()=>{
await group('public metadata/promisify',async()=>{assert.equal(api.generateKeyPair.name,'generateKeyPair');assert.equal(api.generateKeyPair.length,3);assert.equal(api.generateKeyPairSync.length,2);const pairs=await (subject==='native'?util.promisify:api.privateValues.util.promisify)(api.generateKeyPair)('ed25519');return {names:Object.keys(pairs).sort(),type:pairs.publicKey.type};});
await group('validation/errors before init',()=>{const errors=[];for(const type of [undefined,null,3,'rsa2','toString','constructor','ed25519\0junk'])errors.push(error(()=>api.generateKeyPairSync(type,{})));errors.push(error(()=>api.generateKeyPair('rsa',{},null)));errors.push(error(()=>api.generateKeyPairSync('rsa',{modulusLength:0})));errors.push(error(()=>api.generateKeyPairSync('ec',{namedCurve:'bad-curve'})));errors.push(error(()=>api.generateKeyPairSync('dh',{group:'bad-group'})));return errors;});
await group('encoding-getter/algorithm-getter order',()=>{const seen=[];const thrown={tag:'original getter'};const options=new Proxy({publicKeyEncoding:{get format(){seen.push('public.format');return 'pem';},get type(){seen.push('public.type');return 'spki';}},privateKeyEncoding:{get format(){seen.push('private.format');return 'pem';},get type(){seen.push('private.type');return 'pkcs8';},get cipher(){seen.push('private.cipher');return undefined;},get passphrase(){seen.push('private.passphrase');return undefined;}},get modulusLength(){seen.push('modulusLength');throw thrown;}},{get(target,key,receiver){seen.push('options.'+String(key));return Reflect.get(target,key,receiver);}});assert.throws(()=>api.generateKeyPairSync('rsa',options),e=>e===thrown);return seen;});
await group('RSA owned roles/roundtrip',()=>{const pair=api.generateKeyPairSync('rsa',{modulusLength:512,publicExponent:3});assert.equal(pair.privateKey.asymmetricKeyDetails.publicExponent,3n);assert.throws(()=>api.createPrivateKey(pair.publicKey));return checkPair(pair,'rsa');});
await group('RSA-PSS restrictions/encoding',()=>{const pair=api.generateKeyPairSync('rsa-pss',{modulusLength:1024,hashAlgorithm:'sha256',mgf1HashAlgorithm:'sha384',saltLength:12});const details=pair.privateKey.asymmetricKeyDetails;assert.equal(details.hashAlgorithm,'sha256');assert.equal(details.mgf1HashAlgorithm,'sha384');assert.equal(details.saltLength,12);assert.throws(()=>pair.publicKey.export({format:'jwk'}));return {type:pair.privateKey.asymmetricKeyType,details:{modulusLength:details.modulusLength,hashAlgorithm:details.hashAlgorithm,mgf1HashAlgorithm:details.mgf1HashAlgorithm,saltLength:details.saltLength}};});
await group('DSA real paramgen/keygen',()=>checkPair(api.generateKeyPairSync('dsa',{modulusLength:1024,divisorLength:160}),'dsa'));
await group('EC explicit/named',()=>{for(const paramEncoding of ['named','explicit']){const pair=api.generateKeyPairSync('ec',{namedCurve:'prime256v1',paramEncoding});assert.equal(pair.privateKey.asymmetricKeyType,'ec');const signature=native.sign('sha256',Buffer.from('ownership'),pair.privateKey.export({format:'pem',type:'pkcs8'}));assert.equal(native.verify('sha256',Buffer.from('ownership'),pair.publicKey.export({format:'pem',type:'spki'}),signature),true);}return ['named','explicit'];});
await group('DH named/fixed-prime actual ownership',()=>{for(const options of [{group:'modp14'},{prime:native.getDiffieHellman('modp14').getPrime(),generator:2}]){const pair=api.generateKeyPairSync('dh',options);assert.equal(pair.publicKey.asymmetricKeyType,'dh');assert.equal(pair.privateKey.type,'private');assert.throws(()=>pair.publicKey.export({format:'jwk'}));}return ['group','prime'];});
await group('named OKP real provider owners',()=>{const types=[];for(const type of ['ed25519','ed448','x25519','x448']){checkPair(api.generateKeyPairSync(type),type);types.push(type);}return types;});
await group('PEM/encrypted DER genuine bytes',()=>{const pair=api.generateKeyPairSync('rsa',{modulusLength:512,publicKeyEncoding:{format:'pem',type:'spki'},privateKeyEncoding:{format:'der',type:'pkcs8',cipher:'aes-128-cbc',passphrase:'secret'}});assert.equal(typeof pair.publicKey,'string');assert.equal(Buffer.isBuffer(pair.privateKey)||api.Buffer?.isBuffer(pair.privateKey),true);const key=native.createPrivateKey({key:pair.privateKey,format:'der',type:'pkcs8',passphrase:'secret'});const pub=native.createPublicKey(key).export({format:'pem',type:'spki'});assert.equal(pub,pair.publicKey);return {public:'string',private:'buffer',same:true};});
await group('JWK public/private separation',()=>{const pair=api.generateKeyPairSync('ec',{namedCurve:'P-256',publicKeyEncoding:{format:'jwk'},privateKeyEncoding:{format:'jwk'}});assert.equal(pair.publicKey.kty,'EC');assert.equal('d' in pair.publicKey,false);assert.equal(typeof pair.privateKey.d,'string');assert.equal(pair.publicKey.x,pair.privateKey.x);return {kty:pair.publicKey.kty,publicPrivateField:false,privatePrivateField:true};});
await group('EC compressed raw fallback',()=>{const pair=api.generateKeyPairSync('ec',{namedCurve:'P-256',publicKeyEncoding:{format:'raw-public',type:'compressed'},privateKeyEncoding:{format:'raw-private'}});assert.equal(pair.publicKey.length,33);assert.equal(pair.privateKey.length,32);return {public:pair.publicKey.length,private:pair.privateKey.length};});
await group('named raw/PQC actual availability',()=>{const rows=[];for(const type of ['ed25519','ml-dsa-44','ml-kem-512']){const pair=api.generateKeyPairSync(type,{publicKeyEncoding:{format:'raw-public'},privateKeyEncoding:{format:type==='ed25519'?'raw-private':'raw-seed'}});assert.ok(pair.publicKey.length>0);assert.ok(pair.privateKey.length>0);rows.push({type,public:pair.publicKey.length,private:pair.privateKey.length});}return rows;});
await group('async KEYPAIRGENREQUEST/init/callback identity',async()=>{let resource,id,trigger;const hook=createHook({init(n,type,t,r){if(type==='KEYPAIRGENREQUEST'){resource=r;id=n;trigger=t;}}}).enable();const before=executionAsyncId();let pair;try{pair=await asyncPair('ec',{namedCurve:'P-256'});}finally{hook.disable();}assert.equal(pair.job,resource);assert.ok(id>0);assert.equal(trigger,before);assert.equal(pair.job.constructor.name,'EcKeyPairGenJob');return {constructor:pair.job.constructor.name,type:pair.publicKey.type,asyncIdPositive:true};});
await group('async encrypted passphrase snapshot',async()=>{const passphrase=Buffer.from('original');const done=asyncPair('rsa',{modulusLength:512,privateKeyEncoding:{format:'pem',type:'pkcs8',cipher:'aes-128-cbc',passphrase}});passphrase.fill(0);const pair=await done;const key=native.createPrivateKey({key:pair.privateKey,passphrase:'original'});assert.equal(key.type,'private');return {privateType:key.type};});
await group('async frame from actual init',async()=>{const als=new AsyncLocalStorage();const value=await als.run('pair-frame',()=>new Promise((resolve,reject)=>api.generateKeyPair('ed25519',function(error){if(error)return reject(error);resolve(als.getStore());})));assert.equal(value,'pair-frame');return value;});
if(global.gc)global.gc();console.log(JSON.stringify({subject,groups:results,pass:results.filter(r=>r.status==='pass').length,fail:results.filter(r=>r.status!=='pass').length}));if(results.some(r=>r.status!=='pass'))process.exitCode=1;
})();
